const RESULT = { type: 'object', properties: {
  summary: { type: 'string' }, filesChanged: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' },
  cases: { type: 'string' }, deviations: { type: 'array', items: { type: 'string' } },
  needsFromOthers: { type: 'array', items: { type: 'string' } }, needsFromIntegrator: { type: 'array', items: { type: 'string' } },
}, required: ['summary', 'filesChanged', 'tests', 'cases', 'deviations', 'needsFromOthers', 'needsFromIntegrator'] }

phase('Step 2')
const step2 = await agent(`${GO}\n${CTX}\nYOU ARE STEP 2 (ADDENDUM2 §8.7 step 1; alone; you may edit any kernel file for this): write SPEC2's R contract with IN §3.1's DoublesBenchPokemon (carried with sleep, freeze, onceUsed) and hazards.steelsurge — DoublesTurnInput.bench, replacement, hazards, DoublesReplaced, DoublesTurnResult.replaced and hpEntered, DoublesOutcome.benched, MonState.id, World.benched, World.bench, turnNames over the bench, entersWithGas — plus the stubs/hooks R-E fills, keyed on fields nothing sets yet. Gate (behaviour unchanged): npm run check; golden-1v1 --check (only the accepted Fling rows differ from main); all stored app results byte-equal (status2/build step0a-run-app.ts + step0a-diff-app.mjs against a snapshot you take first); compare.ts unchanged. Write scripts/.cache/calc-audit/status2/build/STEP2.md with the hook map for the four tracks.`, { label: 'step2-r-contract', phase: 'Step 2', schema: RESULT })

const TRACKS = [
  ['R-E', 'doubles-switch.ts, doubles-turn.ts, doubles-world.ts, doubles-eot.ts, and for this wave doubles-calling.ts (Assist from the bench\'s moves) and doubles-presence.ts (Beat Up from the bench, Commander\'s newcomer pair keeping notIn2v2("Commander"), Pursuit meeting a switching target at 80); tests/unit/doubles-switch*.test.ts', 'SPEC2 §4.8 + ADDENDUM2 §8.7: replaceSlot, the mid-turn entry pipeline (hazards incl. Steelsurge, entry abilities and items, Neutralizing Gas entering, Intimidate, weather/terrain setters, Commander), identity (MonState.id; later moves into that slot hit the newcomer; Leech Seed/Wish/positions), every switch-out trigger of the family (player-picked and random from the bench, branched exactly), Eject Button / Red Card behind a face, Emergency Exit after a crash and the U-turn family into a face through the calls S and H already make, the end of turn with the newcomer, E2 outcomes with benched Pokémon', 'SWX cases, IN-BNC, IN-HZD, IN-FSL-02, T2P Assist cases, T2E bench landings (as R-V stores them)'],
  ['R-U', 'NU\'s files (app/(app)/calculator/doubles-inputs.ts, EarlierTurnFields.tsx, app/lib/battle/unmodelled-states.ts 2v2 export) and the new BenchFields.tsx, plus the bench state in doubles-prep.ts and the UI files U2 owned (BattleConditions.tsx, useDoublesView.tsx, useDoublesCalculation.ts, doubles-format.ts, DoublesCard.tsx, DoublesTurn.tsx, DoublesSummary.tsx, calculator.module.css, docs/champions-calculator.md, tests/unit/calculator-doubles-*.test.ts)', 'ADDENDUM2 §5.3 / IN §5.7: a Bench per side drawn from the team/roster the slot came from, a replacement pick per Pokémon that can switch out (default the first bench Pokémon with an "Assumes …" fact), Lands this turn over the bench, hazard controls (Stealth Rock, Spikes layers, Toxic Spikes layers, Sticky Web, Steelsurge) per side; the turn panel showing who came in and their entry effects as facts with names; reset rules; 375 px and 1280 px; accessible names unique; facts only', 'UI tests; 375 px; facts-only review'],
  ['R-T', 'app/(app)/training/**, scripts/training/*, tests/unit/training-*', 'SPEC2 §6 R part + ADDENDUM2 §6 R-T: pass Training\'s real bench (the AI\'s own known; the player\'s from the belief world), the replacement policy (rollouts\' rule for the player; the AI\'s own choice for itself as the engine provider already decides switches), hazards, the prelude\'s replacement (the reason "A replacement is needed before the moves." goes), a benched landing source, Assist\'s party; and fix INTEGRATION-1B\'s open item: the belief battle\'s lastMoveTargetLoc after a Future Sight line with no target and after a retarget when the chosen target fainted (3 of 794 fuzz logs)', 'conformance:training, leak:training (0 hits, incl. the bench never leaking the player\'s hidden members), eval:training on main\'s seeds (--run s1-step1), the T2 fuzz'],
  ['R-V', 'scripts/.cache/calc-audit/2v2/verify/**, status2/build/changed-cases.ts, the generated tests/unit/doubles-turn-showdown.test.ts', 'ADDENDUM2 §7 for wave 2: sim-dfs answers mid-turn switch requests with the case\'s replacement and enumerates random drags (Roar, Red Card, Dragon Tail) over the bench; the SWX cases, IN-BNC, IN-HZD, IN-FSL-02, T2P Assist cases, T2E bench landings, in sv plus at least one other game each; run the ORACLE side FIRST and store results so R-E can compare while it builds', 'every wave-2 case agrees; changed-cases.ts lists every changed stored case'],
]

phase('Wave 2')
const tracks = await parallel(TRACKS.map(([key, owns, impl, gate]) => () =>
  agent(`${GO}\n${CTX}\nStep 2 is done: ${JSON.stringify(step2)}\nPARALLEL WORK: four wave-2 tracks edit the same working tree at once, each ONLY in its own files; every other file is frozen (integrator-only: write exact one-line requests with a failing test in needsFromIntegrator). Failures in another track's files are their work in progress: run your tests by path; never edit another track's file. Write notes to scripts/.cache/calc-audit/status2/build/W2-${key}.md.\nYOU ARE TRACK ${key}. You own exclusively: ${owns}. Implement: ${impl}. Gate (checked at integration 2; run what you can now): ${gate}. Add a regression test for every behaviour you add.`, { label: `w2-${key}`, phase: 'Wave 2', schema: RESULT })
    .then(r => ({ key, ...(r || { summary: 'NO RESULT' }) }))))

phase('Integration 2')
const integ = await agent(`${GO}\nYOU ARE THE INTEGRATOR for wave 2; the tracks are finished and you may edit any file of this build (minimal, noted changes).\n${CTX}\nStep 2: ${JSON.stringify(step2 && step2.summary)}\nTrack results: ${JSON.stringify(tracks)}\nTASK (ADDENDUM2 §8.7 step 3, "as 1b, plus the SWX cases and the census sample's switch family"): resolve every need; regenerate status-table.ts; remove REASONS keys whose last site went; run every oracle case (compare.ts), changed-cases.ts, store results, regenerate tests/unit/doubles-turn-showdown.test.ts; npm run check; npm run test:battle-data:source; golden-1v1 --check (only the accepted Fling rows); bench vs main; npm run conformance:training; npm run leak:training; npm run eval:training on main's seeds (--run s1-step1; decision time max under 2000 ms); the census sample (switch family gone except kept reasons) and the budget acceptance; static-render layout checks in the Browser pane at 375 px and 1280 px (no sign-in; never type credentials) of U-turn with a chosen replacement, Parting Shot, Eject Button, Red Card, Roar, Emergency Exit, hazards on entry, a Neutralizing Gas newcomer. Write scripts/.cache/calc-audit/status2/build/INTEGRATION-2.md with each gate's exact output line, fixes and open items.`, {
  label: 'integrator-2', phase: 'Integration 2',
  schema: { type: 'object', properties: { summary: { type: 'string' }, gates: { type: 'string' }, fixes: { type: 'array', items: { type: 'string' } }, open: { type: 'array', items: { type: 'string' } } }, required: ['summary', 'gates', 'fixes', 'open'] },
})

return { step2: step2 && step2.summary, tracks: tracks.map(t => ({ key: t.key, summary: t.summary, deviations: t.deviations })), integ }
